SELECT stored_trigger.trigger_id, stored_trigger.flow_id, stored_trigger.revision, stored_trigger.adapter_kind, stored_trigger.adapter_config_json, stored_trigger.state_json, stored_trigger.enabled, stored_trigger.next_fire_at, stored_trigger.last_fired_at FROM flow_triggers stored_trigger JOIN flows catalog ON catalog.flow_id = stored_trigger.flow_id JOIN flow_definition_revisions revision ON revision.flow_id = stored_trigger.flow_id AND revision.revision = stored_trigger.revision WHERE stored_trigger.enabled = 1 AND catalog.deleted_at IS NULL
